function t(string $key, array $vars = []): string {
    global $LANG;
    $s = UI[$LANG][$key] ?? UI['no'][$key] ?? $key;
    if (!$vars) return $s;
    $map = [];
    foreach ($vars as $k => $v) $map['{' . $k . '}'] = (string)$v;
    return strtr($s, $map);
}
